T = {
'card50_opt1': ("Reboot all the switches", "Reiniciar todos los switches"),
'card50_text': ("Suddenly, the whole network slows down until it stops. The switch lights are blinking like crazy.", "De repente, toda la red se ralentiza hasta pararse. Las luces de los switches parpadean como locas."),
'card50_title': ("The Network Collapses", "La red se hunde"),
'card51_opt0_res0': ("An old virtual machine snapshot was taking up 500 GB! Deleted, everything works again.\n\nDid you know? A snapshot isn't a backup: it grows over time and should be deleted after use.", "¡Un viejo snapshot de máquina virtual ocupaba 500 GB! Borrado, todo vuelve a funcionar.\n\n¿Lo sabías? Un snapshot no es una copia de seguridad: crece con el tiempo y hay que borrarlo después de usarlo."),
'card51_opt0_res1': ("{0.SimFirstName} frees up a little space, but the problem will come back.\n\nDid you know? Quotas limit how much space each user can take.", "{0.SimFirstName} libera algo de espacio, pero el problema volverá.\n\n¿Lo sabías? Las cuotas limitan el espacio que puede ocupar cada usuario."),
'card51_opt0': ("Find what's taking up space", "Buscar qué ocupa espacio"),
'card51_opt1_res0': ("Those were management's training videos… oops.\n\nDid you know? Never delete without knowing what you're deleting (and without a backup).", "Eran los vídeos de formación de la dirección… ups.\n\n¿Lo sabías? Nunca se borra sin saber lo que se borra (y sin copia de seguridad)."),
'card51_opt1': ("Delete the biggest files", "Borrar los archivos más grandes"),
'card51_text': ("The file server says \"Disk full\". Nobody can save anything anymore.", "El servidor de archivos muestra «Disco lleno». Ya nadie puede guardar nada."),
'card51_title': ("The Disk Is Full", "El disco está lleno"),
'card52_opt0_res0': ("Certificate renewed, the padlock is back. {0.SimFirstName} adds an automatic reminder.\n\nDid you know? An SSL/TLS certificate proves a site's identity and encrypts the connection. It has an expiration date.", "Certificado renovado, el candado vuelve. {0.SimFirstName} añade un recordatorio automático.\n\n¿Lo sabías? Un certificado SSL/TLS demuestra la identidad de una web y cifra la conexión. Tiene fecha de caducidad."),
'card52_opt0': ("Renew the HTTPS certificate", "Renovar el certificado HTTPS"),
'card52_opt1_res0': ("Bad idea: you're teaching customers to ignore security warnings!\n\nDid you know? Tools like Let's Encrypt renew certificates automatically.", "Mala idea: ¡estás enseñando a los clientes a ignorar las alertas de seguridad!\n\n¿Lo sabías? Herramientas como Let's Encrypt renuevan los certificados automáticamente."),
'card52_opt1': ("Tell customers to click \"Continue\"", "Decir a los clientes que pulsen «Continuar»"),
'card52_text': ("The company website shows \"Your connection is not private\". Customers are worried.", "La web de la empresa muestra «La conexión no es privada». Los clientes se preocupan."),
'card52_title': ("Expired Certificate", "Certificado caducado"),
'card53_opt0_res0': ("Schedule, tests, department-by-department rollout: the migration goes without drama.\n\nDid you know? A system without updates becomes an open door for hackers.", "Planificación, pruebas, despliegue por departamentos: la migración se hace sin dramas.\n\n¿Lo sabías? Un sistema sin actualizaciones se convierte en una puerta abierta a los atacantes."),
'card53_opt0': ("Prepare a migration plan", "Preparar un plan de migración"),
'card53_opt1_res0': ("A virus exploits an unpatched flaw on these old PCs.\n\nDid you know? \"It still works\" doesn't mean \"it's still safe\".", "Un virus aprovecha un fallo sin corregir en esos equipos viejos.\n\n¿Lo sabías? «Todavía funciona» no significa «todavía es seguro»."),
'card53_opt1_res1': ("Nothing happens… for now.\n\nDid you know? The risk grows every month without updates.", "No pasa nada… por ahora.\n\n¿Lo sabías? El riesgo aumenta cada mes sin actualizaciones."),
'card53_opt1': ("Wait, they still work", "Esperar, todavía funcionan"),
'card53_text': ("About a hundred PCs still run a version of Windows that will no longer get security updates.", "Un centenar de equipos funcionan todavía con una versión de Windows que ya no recibirá actualizaciones de seguridad."),
'card53_title': ("Windows End of Support", "Fin de soporte de Windows"),
'card54_opt0_res0': ("The inventory runs itself, and {0.SimFirstName} finds 12 licenses being paid for nothing!\n\nDid you know? GLPI is used to manage IT assets and tickets: you'll probably use it in your studies.", "El inventario se hace solo, ¡y {0.SimFirstName} encuentra 12 licencias pagadas para nada!\n\n¿Lo sabías? GLPI sirve para gestionar el parque informático y los tickets: seguramente lo usarás en tus estudios."),
'card54_opt0': ("Install an inventory tool (GLPI)", "Instalar una herramienta de inventario (GLPI)"),
'card54_opt1_res0': ("Two days of counting… and already wrong the following week.\n\nDid you know? An automatic inventory updates itself.", "Dos días contando… y ya está desfasado la semana siguiente.\n\n¿Lo sabías? Un inventario automático se actualiza solo."),
'card54_opt1': ("Count by hand in a spreadsheet", "Contar a mano en una hoja de cálculo"),
'card54_text': ("Management asks how many computers, screens and licenses the company owns.", "La dirección pregunta cuántos ordenadores, pantallas y licencias tiene la empresa."),
'card54_title': ("The Asset Inventory", "El inventario del parque"),
'card55_opt0_res0': ("Monday, 9 AM, everything is ready. The newcomer is impressed.\n\nDid you know? Onboarding (welcoming new hires) goes better with a written procedure.", "Lunes, 9:00, todo está listo. El recién llegado está impresionado.\n\n¿Lo sabías? La acogida de nuevos empleados (onboarding) funciona mejor con un procedimiento escrito."),
'card55_opt0': ("Prepare everything the day before with a checklist", "Prepararlo todo la víspera con una lista"),
'card55_opt1_res0': ("The newcomer waits all morning without a computer.\n\nDid you know? First impressions matter for the IT department too!", "El recién llegado espera toda la mañana sin ordenador.\n\n¿Lo sabías? ¡La primera impresión también cuenta para el departamento de informática!"),
'card55_opt1': ("Deal with it Monday morning", "Encargarse el lunes por la mañana"),
'card55_text': ("A new sales rep starts on Monday. They need a PC, an account, an email address and a badge.", "Un nuevo comercial llega el lunes. Necesita un equipo, una cuenta, un correo y una tarjeta."),
'card55_title': ("A New Hire Arrives", "Llega alguien nuevo"),
'card56_opt0_res0': ("Account disabled, VPN cut, badge blocked. Nothing to worry about.\n\nDid you know? A former employee's account that's still active is a classic security hole.", "Cuenta desactivada, VPN cortada, tarjeta bloqueada. Nada que temer.\n\n¿Lo sabías? La cuenta de un exempleado todavía activa es un fallo de seguridad clásico."),
'card56_opt0': ("Disable all their access immediately", "Desactivar todos sus accesos de inmediato"),
'card56_opt1_res0': ("On Monday, he logged in remotely and deleted folders…\n\nDid you know? The offboarding procedure must be as rigorous as onboarding.", "El lunes, se conectó a distancia y borró carpetas…\n\n¿Lo sabías? El procedimiento de salida debe ser tan riguroso como el de llegada."),
'card56_opt1_res1': ("Nothing happened, this time.\n\nDid you know? Don't count on luck: access is disabled on the day someone leaves.", "No ha pasado nada, esta vez.\n\n¿Lo sabías? No cuentes con la suerte: los accesos se desactivan el día de la salida."),
'card56_opt1': ("Do it later", "Hacerlo más tarde"),
'card56_text': ("An employee left the company on Friday… angry.", "Un empleado dejó la empresa el viernes… enfadado."),
'card56_title': ("An Employee Leaves", "La salida de un empleado"),
'card57_opt0_res0': ("The backup link takes over: Internet is back, slower but working.\n\nDid you know? Redundancy (a second link) keeps a single failure from blocking everything.", "El enlace de respaldo toma el relevo: Internet vuelve, más lento pero funcional.\n\n¿Lo sabías? La redundancia (un segundo enlace) evita que una sola avería lo bloquee todo."),
'card57_opt0_res1': ("The backup router had never been configured…\n\nDid you know? An untested backup plan is useless on the day you need it.", "El router de respaldo nunca se había configurado…\n\n¿Lo sabías? Un plan de respaldo sin probar no sirve de nada el día D."),
'card57_opt0': ("Switch to the backup 4G line", "Pasar a la línea 4G de respaldo"),
'card57_opt1_res0': ("A whole day without Internet. Management is not happy.\n\nDid you know? A business continuity plan (BCP) sets out how to keep working during an outage.", "Un día entero sin Internet. La dirección no está contenta.\n\n¿Lo sabías? El plan de continuidad de negocio prevé cómo seguir trabajando durante una avería."),
'card57_opt1': ("Wait for the repair", "Esperar la reparación"),
'card57_text': ("Roadworks cut the fiber: no more Internet at the company.", "Unas obras en la calle han cortado la fibra: la empresa se queda sin Internet."),
'card57_title': ("The Fiber Is Cut", "La fibra está cortada"),
'card58_opt0_res0': ("The temperature drops, the important servers hold until the repair.\n\nDid you know? Servers produce a lot of heat: above roughly 27 °C (80 °F), you risk failures.", "La temperatura baja y los servidores importantes aguantan hasta la reparación.\n\n¿Lo sabías? Los servidores se calientan mucho: por encima de unos 27 °C hay riesgo de averías."),
'card58_opt0': ("Shut down non-essential servers", "Apagar los servidores no esenciales"),
'card58_opt1_res0': ("It's not enough: a server overheats and shuts down.\n\nDid you know? A temperature sensor in the monitoring system would have raised the alarm earlier.", "No basta: un servidor se sobrecalienta y se apaga.\n\n¿Lo sabías? Una sonda de temperatura en la supervisión habría dado la alerta antes."),
'card58_opt1_res1': ("The makeshift fix works, it holds!\n\nDid you know? It's a temporary solution: the AC has to be fixed as soon as possible.", "¡El apaño funciona, aguanta!\n\n¿Lo sabías? Es una solución provisional: hay que reparar el aire acondicionado cuanto antes."),
'card58_opt1': ("Open the door and add a fan", "Abrir la puerta y poner un ventilador"),
'card58_text': ("The server room air conditioning is broken. It's already 35 °C (95 °F) inside.", "El aire acondicionado de la sala de servidores está averiado. Ya hace 35 °C dentro."),
'card58_title': ("The Server Room AC", "El aire acondicionado de la sala de servidores"),
'card59_opt0_res0': ("He grumbles, but his PC stays clean and secure.\n\nDid you know? The principle of least privilege: everyone only gets the rights they need.", "Refunfuña, pero su equipo sigue limpio y seguro.\n\n¿Lo sabías? El principio de mínimo privilegio: cada uno solo tiene los permisos que necesita."),
'card59_opt0': ("Refuse and install the software for him", "Negarse e instalarle los programas"),
'card59_opt1_res0': ("He installed a fake free program… full of ads and spyware.\n\nDid you know? With admin rights, a virus can do anything on the PC.", "Ha instalado un falso programa gratuito… lleno de publicidad y espías.\n\n¿Lo sabías? Con permisos de administrador, un virus puede hacer de todo en el equipo."),
'card59_opt1': ("Give him the rights", "Darle los permisos"),
'card59_text': ("A user demands administrator rights on his PC \"to install a few small programs\".", "Un usuario exige permisos de administrador en su equipo «para instalar programitas»."),
'card59_title': ("\"I Want to Be an Administrator\"", "«Quiero ser administrador»"),
'card60_opt0_res0': ("Everyone has their own account, and you know who does what.\n\nDid you know? With sudo, you only take root rights when needed, and it's recorded in the logs.", "Cada uno tiene su cuenta y se sabe quién hace qué.\n\n¿Lo sabías? Con sudo, solo se toman los permisos de root cuando hace falta, y queda registrado."),
'card60_opt0_res1': ("{0.SimFirstName} locks themselves out while editing the SSH config…\n\nDid you know? Before changing SSH, keep a session open so you can undo.", "{0.SimFirstName} se queda fuera al modificar la configuración SSH…\n\n¿Lo sabías? Antes de tocar SSH, se deja una sesión abierta para poder deshacer."),
'card60_opt0': ("Create personal accounts and use sudo", "Crear cuentas personales y usar sudo"),
'card60_opt1_res0': ("One day, someone deletes an important folder… impossible to know who.\n\nDid you know? Shared accounts prevent traceability.", "Un día, alguien borra una carpeta importante… imposible saber quién.\n\n¿Lo sabías? Las cuentas compartidas impiden la trazabilidad."),
'card60_opt1': ("Leave it as is", "Dejarlo así"),
'card60_text': ("On the Linux server, everyone logs in over SSH with the root account and the same password.", "En el servidor Linux, todo el mundo se conecta por SSH con la cuenta root y la misma contraseña."),
'card60_title': ("Logging In as Root", "Conexión como root"),
'card61_opt0_res0': ("Update done in the evening, config backed up first. Zero downtime during the day.\n\nDid you know? Always back up a device's configuration before updating it.", "Actualización hecha por la noche, con copia de la configuración antes. Cero cortes durante el día.\n\n¿Lo sabías? Siempre se guarda la configuración de un equipo antes de actualizarlo."),
'card61_opt0': ("Schedule the update for an evening", "Programar la actualización una noche"),
'card61_opt1_res0': ("The router reboots: 15 minutes without network for the whole company.\n\nDid you know? Work that interrupts service is done outside business hours.", "El router se reinicia: 15 minutos sin red para toda la empresa.\n\n¿Lo sabías? Las intervenciones que cortan el servicio se hacen fuera del horario laboral."),
'card61_opt1': ("Do it right now in the middle of the day", "Hacerla ya, en pleno día"),
'card61_text': ("The maker of the main router releases a firmware update.", "El fabricante del router principal publica una actualización de firmware."),
'card61_title': ("Router Update", "Actualización del router"),
'card62_opt0_res0': ("Calls get priority: no more dropouts!\n\nDid you know? QoS (quality of service) gives certain traffic, like voice, priority on the network.", "Las llamadas tienen prioridad: ¡se acabaron los cortes!\n\n¿Lo sabías? La QoS (calidad de servicio) da prioridad en la red a ciertos flujos, como la voz."),
'card62_opt0_res1': ("The configuration is complicated, you'll have to come back to it.\n\nDid you know? Telephony is often put in its own VLAN (voice VLAN).", "La configuración es complicada, habrá que volver a ella.\n\n¿Lo sabías? La telefonía suele ponerse en una VLAN aparte (VLAN de voz)."),
'card62_opt0': ("Configure QoS on the switches", "Configurar la QoS en los switches"),
'card62_opt1_res0': ("Users are furious and work around the ban.\n\nDid you know? A rule that's too strict pushes people to bypass it.", "Los usuarios están furiosos y se saltan la prohibición.\n\n¿Lo sabías? Una regla demasiado estricta empuja a la gente a saltársela."),
'card62_opt1': ("Ban downloads", "Prohibir las descargas"),
'card62_text': ("Since switching to IP telephony, calls drop whenever someone downloads a big file.", "Desde el paso a la telefonía IP, las llamadas se cortan cuando alguien descarga un archivo grande."),
'card62_title': ("The Phones Are Crackling", "Los teléfonos chisporrotean"),
'card63_opt0_res0': ("Both sites are linked like a single network, securely.\n\nDid you know? A site-to-site VPN permanently connects two networks through an encrypted tunnel over the Internet.", "Las dos sedes quedan unidas como una sola red, con total seguridad.\n\n¿Lo sabías? Una VPN sitio a sitio une dos redes de forma permanente con un túnel cifrado por Internet."),
'card63_opt0_res1': ("The tunnel comes up, but drops every hour.\n\nDid you know? Both sides of the VPN must have exactly the same settings.", "El túnel se levanta, pero se cae cada hora.\n\n¿Lo sabías? Los dos extremos de la VPN deben tener exactamente los mismos parámetros."),
'card63_opt0': ("Set up a site-to-site VPN", "Montar una VPN sitio a sitio"),
'card63_opt1_res0': ("Within a few hours, hacker bots are already trying passwords…\n\nDid you know? Never expose an internal server directly to the Internet.", "En pocas horas, unos robots atacantes ya prueban contraseñas…\n\n¿Lo sabías? Nunca se expone un servidor interno directamente a Internet."),
'card63_opt1': ("Open the servers to the Internet", "Abrir los servidores a Internet"),
'card63_text': ("The company is opening a branch in another city. It needs access to the headquarters servers.", "La empresa abre una sucursal en otra ciudad. Necesita acceder a los servidores de la sede."),
'card63_title': ("A New Office to Connect", "Una nueva oficina que conectar"),
'card64_opt0_res0': ("{0.SimFirstName} adds space before the server fills up. Nobody noticed a thing.\n\nDid you know? Monitoring is there so you can act BEFORE the outage.", "{0.SimFirstName} añade espacio antes de que el servidor se llene. Nadie ha notado nada.\n\n¿Lo sabías? La supervisión sirve para actuar ANTES de la avería."),
'card64_opt0': ("Act right away", "Actuar de inmediato"),
'card64_opt1_res0': ("The disk is full the next day: no email for 3 hours.\n\nDid you know? An ignored alert always ends up becoming an outage.", "Al día siguiente el disco está lleno: 3 horas sin correo.\n\n¿Lo sabías? Una alerta ignorada siempre acaba convirtiéndose en avería."),
'card64_opt1': ("Deal with it next week", "Encargarse la semana que viene"),
'card64_text': ("Monitoring shows: \"Mail server disk: 92%\".", "La supervisión muestra: «Disco del servidor de correo: 92 %»."),
'card64_title': ("The Monitoring Alert", "La alerta de supervisión"),
'card65_opt0_res0': ("Everything is up to date, the auditor is impressed.\n\nDid you know? An addressing plan lists the networks, masks and addresses of every device.", "Todo está al día y el auditor está impresionado.\n\n¿Lo sabías? Un plan de direccionamiento lista las redes, las máscaras y las direcciones de cada equipo."),
'card65_opt0_res1': ("The docs are a year out of date… {0.SimFirstName} updates them in a rush.\n\nDid you know? Docs are updated with every change, otherwise they're useless.", "La documentación lleva un año de retraso… {0.SimFirstName} la actualiza de urgencia.\n\n¿Lo sabías? La documentación se actualiza con cada cambio; si no, no sirve de nada."),
'card65_opt0': ("Pull it from the documentation", "Sacarlo de la documentación"),
'card65_opt1_res0': ("The auditor finds 4 mistakes. Bad mark.\n\nDid you know? Tools like draw.io help make clean network diagrams.", "El auditor encuentra 4 errores. Mala nota.\n\n¿Lo sabías? Herramientas como draw.io ayudan a hacer esquemas de red limpios."),
'card65_opt1': ("Draw it from memory", "Dibujarlo de memoria"),
'card65_text': ("An auditor asks for the network diagram and the IP addressing plan.", "Un auditor pide el esquema de la red y el plan de direccionamiento IP."),
'card65_title': ("The Auditor Wants the Diagram", "El auditor quiere el esquema"),
'card66_opt0_res0': ("Accounting, HR, production: each department has its own subnet. Clean!\n\nDid you know? A /24 has 254 usable addresses. Splitting it into /26s gives you 4 networks of 62 addresses.", "Contabilidad, RR. HH., producción: cada departamento tiene su subred. ¡Impecable!\n\n¿Lo sabías? Un /24 tiene 254 direcciones utilizables. Dividiéndolo en /26 se obtienen 4 redes de 62 direcciones."),
'card66_opt0_res1': ("A calculation error: two departments have overlapping ranges.\n\nDid you know? Check your math with a subnet calculator.", "Un error de cálculo: dos departamentos tienen rangos que se solapan.\n\n¿Lo sabías? Los cálculos se comprueban con una calculadora de subredes."),
'card66_opt0': ("Calculate the subnets", "Calcular las subredes"),
}
